"""Deterministic generators for the built-in fraction question set."""

import random
from fractions import Fraction

from .models import Question, QuestionType, fraction_to_text

_DEFAULT_SEED = 20240101


def _unique_options(correct, distractors, rng, count=4):
    """Return a shuffled tuple of options containing exactly one correct answer."""
    seen = {correct}
    chosen = [correct]
    for candidate in distractors:
        if candidate not in seen:
            seen.add(candidate)
            chosen.append(candidate)
        if len(chosen) == count:
            break
    fallbacks = [
        fraction_to_text(Fraction(1, 2)),
        fraction_to_text(Fraction(1, 3)),
        fraction_to_text(Fraction(1, 4)),
        fraction_to_text(Fraction(2, 3)),
        "0",
        "1",
    ]
    for candidate in fallbacks:
        if candidate not in seen:
            seen.add(candidate)
            chosen.append(candidate)
        if len(chosen) == count:
            break
    rng.shuffle(chosen)
    return tuple(chosen)


def _arithmetic_question(qid, left, right, operator, rng):
    if operator == "+":
        value = left + right
        symbol = " + "
        qtype = QuestionType.ADD
    elif operator == "-":
        value = left - right
        symbol = " - "
        qtype = QuestionType.SUBTRACT
    else:
        value = left * right
        symbol = " × "
        qtype = QuestionType.MULTIPLY

    correct = fraction_to_text(value)
    distractors = [
        fraction_to_text(left + right),
        fraction_to_text(left - right),
        fraction_to_text(left * right),
        fraction_to_text(value + Fraction(1, 2)),
        fraction_to_text(value + 1),
    ]
    options = _unique_options(correct, distractors, rng)
    prompt = f"What is {fraction_to_text(left)}{symbol}{fraction_to_text(right)}?"
    return Question(id=qid, prompt=prompt, options=options, correct_answer=correct, question_type=qtype)


def _simplify_question(qid, numerator, denominator, rng):
    value = Fraction(numerator, denominator)
    correct = fraction_to_text(value)
    distractors = [
        fraction_to_text(Fraction(numerator, denominator + 1)),
        fraction_to_text(Fraction(numerator + 1, denominator)),
        fraction_to_text(Fraction(numerator - 1, denominator)) if numerator > 1 else fraction_to_text(value + 1),
        fraction_to_text(value + 1),
    ]
    options = _unique_options(correct, distractors, rng)
    prompt = f"Simplify the fraction {numerator}/{denominator}."
    return Question(id=qid, prompt=prompt, options=options, correct_answer=correct, question_type=QuestionType.SIMPLIFY)


def _compare_question(qid, left, right, rng):
    if left > right:
        correct = ">"
    elif left < right:
        correct = "<"
    else:
        correct = "="
    options = [">", "<", "="]
    rng.shuffle(options)
    prompt = f"Choose the correct symbol: {fraction_to_text(left)} ? {fraction_to_text(right)}"
    return Question(id=qid, prompt=prompt, options=tuple(options), correct_answer=correct, question_type=QuestionType.COMPARE)


def default_questions(rng=None):
    """Return the built-in question set used for a fresh install."""
    rng = rng or random.Random(_DEFAULT_SEED)
    questions = []
    qid = 1
    questions.append(_arithmetic_question(qid, Fraction(1, 2), Fraction(1, 3), "+", rng)); qid += 1
    questions.append(_arithmetic_question(qid, Fraction(3, 4), Fraction(1, 4), "-", rng)); qid += 1
    questions.append(_arithmetic_question(qid, Fraction(2, 3), Fraction(3, 5), "+", rng)); qid += 1
    questions.append(_arithmetic_question(qid, Fraction(5, 6), Fraction(1, 2), "-", rng)); qid += 1
    questions.append(_arithmetic_question(qid, Fraction(1, 2), Fraction(2, 3), "*", rng)); qid += 1
    questions.append(_arithmetic_question(qid, Fraction(3, 5), Fraction(5, 7), "*", rng)); qid += 1
    questions.append(_simplify_question(qid, 4, 8, rng)); qid += 1
    questions.append(_simplify_question(qid, 9, 12, rng)); qid += 1
    questions.append(_simplify_question(qid, 15, 25, rng)); qid += 1
    questions.append(_compare_question(qid, Fraction(3, 4), Fraction(2, 3), rng)); qid += 1
    questions.append(_compare_question(qid, Fraction(1, 2), Fraction(4, 8), rng)); qid += 1
    questions.append(_compare_question(qid, Fraction(7, 10), Fraction(3, 5), rng)); qid += 1
    return questions
